return [{ json: { keywords: explicit && requested.length ? requested : terms([...manualKeywords, ...autoKeywords, ...talentSearchKeywords]), keywordConfig: { schemaVersion: Number(config.schemaVersion || 1), manualKeywords, excludedKeywords, maxAutoKeywords: Math.max(0, Math.floor(Number(config.maxAutoKeywords ?? 30) || 0)) }, talentSearchKeywords, talentKeywordCount: talentSearchKeywords.length, keywordConfigPath: 'config/keywords.json', lookbackHours: positive(input.lookbackHours ?? input.lookback_hours, 24), maxArticles: optionalPositive(input.maxArticles ?? input.max_articles), locale: input.locale ?? 'ja-JP', language: input.language ?? 'ja', country: input.country ?? 'JP', outputLanguage: input.outputLanguage ?? input.output_language ?? 'ja', source: webhook ? 'webhook-request' : 'default-daily-request' } }];

const webhook = $('Keyword Candidate Add Webhook').first().json ?? {};
const body = webhook.body ?? webhook;
const keyword = String(body.keyword ?? '').trim();
const candidateDate = String(body.candidateDate ?? '').trim();
const source = String(body.source ?? '').trim();
const config = $input.first().json.keywordConfig ?? {};
const terms = (value) => { const seen = new Set(); return (Array.isArray(value) ? value : String(value ?? '').split(/,|\n/)).reduce((all, value) => { const term = String(value || '').trim(); const key = normalize(term); if (term && !seen.has(key)) { seen.add(key); all.push(term); } return all; }, []); };
const normalize = (value) => String(value || '').trim().replaceAll('！', '!').toLocaleLowerCase('ja-JP');
const manualKeywords = terms(config.manualKeywords);
const excludedKeywords = new Set(terms(config.excludedKeywords).map(normalize));
const maxAutoKeywords = Math.max(0, Math.floor(Number(config.maxAutoKeywords ?? 30) || 0));
const staticData = $getWorkflowStaticData('global');
const autoKeywords = terms(staticData.autoKeywords);
const current = [...manualKeywords, ...autoKeywords];
const key = normalize(keyword);
const respond = (status, reason, added) => [{ json: { status, keyword, reason, added, autoKeywordCount: autoKeywords.length } }];

if (source !== 'talent-dashboard') return respond('rejected', 'This webhook only accepts requests from the local Talent Index dashboard.', false);
if (!/^\d{4}-\d{2}-\d{2}$/.test(candidateDate)) return respond('rejected', 'candidateDate must use YYYY-MM-DD.', false);
if (keyword.length < 2 || keyword.length > 30 || /[|/\\]/.test(keyword) || /^https?:/i.test(keyword)) return respond('rejected', 'The keyword format is not allowed.', false);
if (excludedKeywords.has(key)) return respond('rejected', 'The keyword is excluded by config/keywords.json.', false);
if (current.some((term) => normalize(term) === key)) return respond('already_added', 'The keyword is already configured.', false);
if (autoKeywords.length >= maxAutoKeywords) return respond('rejected', `The automatic keyword limit (${maxAutoKeywords}) has been reached.`, false);

autoKeywords.push(keyword);
staticData.autoKeywords = autoKeywords;
const history = Array.isArray(staticData.manualKeywordAdditions) ? staticData.manualKeywordAdditions : [];
const addition = { term: keyword, candidateDate, source, addedAt: new Date().toISOString() };
staticData.manualKeywordAdditions = [...history, addition].slice(-100);
staticData.lastManualKeywordAddition = addition;
return [{ json: { status: 'added', keyword, reason: 'Saved to workflow static data.', added: true, autoKeywordCount: autoKeywords.length } }];

const webhook = $('Keyword Management Webhook').first().json ?? {};
const body = webhook.body ?? webhook;
const operation = String(body.operation ?? '').trim().toLowerCase();
let keyword = String(body.keyword ?? '').trim();
const previousKeyword = String(body.previousKeyword ?? '').trim();
const source = String(body.source ?? '').trim();
const config = $input.first().json.keywordConfig ?? {};
const normalize = (value) => String(value || '').trim().replaceAll('！', '!').toLocaleLowerCase('ja-JP');
const terms = (value) => { const seen = new Set(); return (Array.isArray(value) ? value : String(value ?? '').split(/,|\n/)).reduce((all, value) => { const term = String(value || '').trim(); const key = normalize(term); if (term && !seen.has(key)) { seen.add(key); all.push(term); } return all; }, []); };
const manualKeywords = terms(config.manualKeywords);
const excludedKeywords = new Set(terms(config.excludedKeywords).map(normalize));
const maxAutoKeywords = Math.max(0, Math.floor(Number(config.maxAutoKeywords ?? 30) || 0));
const staticData = $getWorkflowStaticData('global');
const autoKeywords = terms(staticData.autoKeywords);
const respond = (status, reason, value = keyword || previousKeyword, changed = false) => [{ json: { status, keyword: value, reason, changed, autoKeywordCount: autoKeywords.length } }];
const validKeyword = (value) => value.length >= 2 && value.length <= 30 && !/[|/\\]/.test(value) && !/^https?:/i.test(value);

if (source !== 'talent-dashboard') return respond('rejected', 'This webhook only accepts requests from the local Talent Index dashboard.');
if (!['add', 'edit', 'remove'].includes(operation)) return respond('rejected', 'operation must be add, edit, or remove.');
if (operation !== 'remove' && !validKeyword(keyword)) return respond('rejected', 'The keyword format is not allowed.');
if ((operation === 'edit' || operation === 'remove') && !previousKeyword) return respond('rejected', 'previousKeyword is required.');
if (operation !== 'remove' && excludedKeywords.has(normalize(keyword))) return respond('rejected', 'The keyword is excluded by config/keywords.json.');
if (operation !== 'remove' && manualKeywords.some((term) => normalize(term) === normalize(keyword))) return respond('already_added', 'The keyword is already configured manually.');

let status = 'rejected';
let reason = '';
let changed = false;
if (operation === 'add') {
  if (autoKeywords.some((term) => normalize(term) === normalize(keyword))) return respond('already_added', 'The keyword is already configured.');
  if (autoKeywords.length >= maxAutoKeywords) return respond('rejected', `The automatic keyword limit (${maxAutoKeywords}) has been reached.`);
  autoKeywords.push(keyword);
  status = 'added'; reason = 'Saved to workflow static data.'; changed = true;
} else {
  const index = autoKeywords.findIndex((term) => normalize(term) === normalize(previousKeyword));
  if (index < 0) return respond(operation === 'remove' ? 'already_removed' : 'rejected', operation === 'remove' ? 'The keyword was already removed.' : 'The keyword no longer exists.');
  if (operation === 'remove') {
    const removed = autoKeywords.splice(index, 1)[0];
    keyword = removed;
    status = 'removed'; reason = 'Removed from workflow static data.'; changed = true;
  } else if (normalize(autoKeywords[index]) === normalize(keyword)) {
    return respond('unchanged', 'The keyword did not change.', autoKeywords[index]);
  } else if (autoKeywords.some((term, position) => position !== index && normalize(term) === normalize(keyword))) {
    return respond('rejected', 'The keyword already exists.');
  } else {
    autoKeywords[index] = keyword;
    status = 'updated'; reason = 'Updated in workflow static data.'; changed = true;
  }
}

if (changed) {
  staticData.autoKeywords = autoKeywords;
  const history = Array.isArray(staticData.dashboardKeywordManagement) ? staticData.dashboardKeywordManagement : [];
  staticData.dashboardKeywordManagement = [...history, { operation, keyword, previousKeyword, changedAt: new Date().toISOString() }].slice(-100);
  staticData.lastDashboardKeywordManagement = staticData.dashboardKeywordManagement.at(-1);
}
return respond(status, reason, keyword, changed);

const data = $('Normalize and Deduplicate Articles').first().json;
const feedbackRows = $input.all().map((item) => item.json ?? {});
const isRejected = (value) => value === true || value === 1 || ['1', 'true', 'yes'].includes(String(value ?? '').trim().toLocaleLowerCase('ja-JP'));
const rejected = feedbackRows.filter((row) => row.article_key && isRejected(row.is_rejected));
const exactUrls = new Set(rejected.map((row) => String(row.article_url ?? '').trim()).filter(Boolean));
const sourceDomains = new Set(rejected
  .filter((row) => String(row.reason_code ?? '') === 'suspicious_source')
  .map((row) => String(row.source_domain ?? '').trim().toLocaleLowerCase('ja-JP').replace(/^www\./, ''))
  .filter(Boolean));
const publisherLabels = new Set(rejected
  .filter((row) => String(row.reason_code ?? '') === 'suspicious_source')
  .map((row) => String(row.publisher_label ?? '').trim().toLocaleLowerCase('ja-JP'))
  .filter(Boolean));
const titleSignatures = new Set(rejected
  .filter((row) => String(row.reason_code ?? '') === 'irrelevant')
  .map((row) => String(row.title_signature ?? '').trim().toLocaleLowerCase('ja-JP'))
  .filter(Boolean));

function canonicalTitle(value) {
  return String(value ?? '')
    .replace(/\s+(?:-|｜|–|—)\s+\S.*$/, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLocaleLowerCase('ja-JP');
}
function publisherLabel(article) {
  const source = String(article.source ?? '').trim();
  if (source) return source.replace(/\s+/g, ' ').toLocaleLowerCase('ja-JP');
  const title = String(article.title ?? '').trim();
  const match = title.match(/\s+(?:-|｜|–|—)\s+(.+)$/);
  return match ? match[1].replace(/\s+/g, ' ').trim().toLocaleLowerCase('ja-JP') : '';
}
function sourceDomain(article) {
  try {
    const hostname = new URL(String(article.url ?? '')).hostname.toLocaleLowerCase('ja-JP').replace(/^www\./, '');
    return ['news.google.com', 'b.hatena.ne.jp'].includes(hostname) ? '' : hostname;
  } catch (error) {
    return '';
  }
}

let excludedArticleCount = 0;
const articles = (Array.isArray(data.articles) ? data.articles : []).filter((article) => {
  const url = String(article.url ?? '').trim();
  const rejectedByUrl = url && exactUrls.has(url);
  const rejectedByDomain = sourceDomains.has(sourceDomain(article));
  const rejectedByPublisher = publisherLabels.has(publisherLabel(article));
  const rejectedByTitle = titleSignatures.has(canonicalTitle(article));
  const rejectedArticle = rejectedByUrl || rejectedByDomain || rejectedByPublisher || rejectedByTitle;
  if (rejectedArticle) excludedArticleCount += 1;
  return !rejectedArticle;
});

return [{
  json: {
    ...data,
    articleCount: articles.length,
    excludedArticleCount,
    articles,
  },
}];
